"Darstellung":"Utseende",
"Darstellung (A)":"Utseende (A)",
"Darstellung (A): Material auf Körper ziehen":"Utseende (A): dra materiale på kropper",
"Darstellung auf einen Körper ziehen.":"Dra et utseende på en kropp.",
"Darstellung der Körper":"Visning av kropper",
"Darstellung wird aufbereitet …":"Klargjør visning …",
"Darstellung zurückgesetzt (vom Material).":"Utseende tilbakestilt (fra materialet).",
"Darstellung „{0}“ auf {1} Körper angewendet.":"Utseende «{0}» brukt på {1} kropper.",
"Darstellungsqualität":"Visningskvalitet",
"Das Bild konnte nicht gelesen werden.":"Bildet kunne ikke leses.",
"Das Bild liegt als Vorlage auf der Ebene. Größe, Lage, Drehung und Deckkraft danach im Eigenschaftenfenster einstellen (z. B. Breite nach einer bekannten Abmessung).":"Bildet ligger som mal på planet. Still deretter inn størrelse, posisjon, rotasjon og dekkevne i egenskapsvinduet (f.eks. bredde etter et kjent mål).",
"Das Ergebnis des Geometriekerns ist unlesbar":"Resultatet fra geometrikjernen er uleselig",
"Das Ergebnis konnte nicht geschrieben werden":"Resultatet kunne ikke skrives",
"Das Maß muss größer als 0 sein.":"Målet må være større enn 0.",
"Das Netz bleibt ein Dreiecksnetz (kein B-Rep). Bearbeiten unter NETZ: Reparieren, Reduzieren, Glätten, Ebenenschnitt … 3D-Frässtrategien in der Fertigung können es direkt bearbeiten.":"Nettet forblir et trekantnett (ikke B-Rep). Rediger under NETT: Reparer, Reduser, Glatt, Plansnitt … 3D-frestrategier i produksjon kan bearbeide det direkte.",
"Das Profil darf die Achse nicht schneiden. Eine offene Linie in der Skizze kann als Achse dienen.":"Profilen må ikke krysse aksen. En åpen linje i skissen kan brukes som akse.",
"Das Profil mit den jetzigen Werten überschreiben":"Overskriv profilen med de gjeldende verdiene",
"Das Profil wird entlang einer Linie/eines Linienzugs geführt. Profil am besten senkrecht zum Pfadanfang zeichnen (z. B. Profil auf XZ, Pfad auf XY).":"Profilen føres langs en linje/polylinje. Tegn helst profilen vinkelrett på banens start (f.eks. profil på XZ, bane på XY).",
"Das Profil wird von der Skizzenebene aus erhaben oder vertieft geprägt.":"Profilen prestes opphøyd eller nedsenket fra skisseplanet.",
"Das Rohteil ist der Quader um den gewählten Körper (plus Versatz).":"Råemnet er kvaderen rundt den valgte kroppen (pluss forskyvning).",
"Das Setup hat keine Operationen.":"Oppspenningen har ingen operasjoner.",
"Das Werkzeug fräst in Kreisen, deren Mitte entlang der Nut wandert. Es ist nie über die volle Breite im Eingriff – das erlaubt große Zustelltiefen und schont Fräser und Spindel. Der Fräser sollte etwa 60 % der Nutbreite haben.":"Verktøyet freser i sirkler hvis midtpunkt vandrer langs sporet. Det er aldri i inngrep over full bredde – det tillater store skjæredybder og skåner fres og spindel. Fresen bør være omtrent 60 % av sporbredden.",
"Das Werkzeug schneidet die Fläche nicht":"Verktøyet skjærer ikke flaten",
"Das Werkzeug schneidet in Richtung der ausgewählten Flächen, bis es die angegebenen Aufmaße erreicht.":"Verktøyet skjærer i retning av de valgte flatene til det når de angitte overmålene.",
"Das Werkzeug taucht wie ein Bohrer senkrecht ein, Reihe für Reihe, bis auf das Modell plus Aufmaß. Die Schnittkraft wirkt entlang der Spindel: geeignet für lange Werkzeuge, tiefe Kavitäten und wenig steife Maschinen. Das Werkzeug muss über die Mitte schneiden.{0}":"Verktøyet stikker loddrett ned som en bor, rad for rad, ned til modellen pluss overmål. Skjærekraften virker langs spindelen: egnet for lange verktøy, dype kaviteter og lite stive maskiner. Verktøyet må skjære over midten.{0}",
"Das Werkzeug vermeidet diese Flächen unter Berücksichtigung der angegebenen Sicherheitsabstände (Spanner, Schraubstock).":"Verktøyet unngår disse flatene under hensyn til de angitte sikkerhetsavstandene (spenner, skrustikke).",
"Das Werkzeug vermeidet diese Flächen, während es in der Nähe liegende Flächen bearbeitet, und hält die Sicherheitsabstände ein.":"Verktøyet unngår disse flatene mens det bearbeider flater i nærheten, og overholder sikkerhetsavstandene.",
"Das erste Esc bricht nur das Werkzeug oder die Auswahl ab – ein Esc zu viel schließt die Skizze nicht":"Første Esc avbryter bare verktøyet eller valget – en Esc for mye lukker ikke skissen",
"Das ist keine Bohrung (Verrundung oder Zapfen) – bitte die Innenwand einer Bohrung anklicken.":"Dette er ikke et hull (avrunding eller tapp) – klikk på innsiden av et hull.",
"Das ist keine Bohrung (Zylinderfläche) – bitte die Bohrungswand anklicken.":"Dette er ikke et hull (sylinderflate) – klikk på hullveggen.",
"Das ist keine WerkFab-Design-Datei.":"Dette er ikke en WerkFab-designfil.",
"Das ist keine schräge Kante – beide Enden der Fasenkante anklicken.":"Dette er ikke en skrå kant – klikk på begge endene av faskanten.",
"Datei":"Fil",
"Datei ist keine WerkFab-Einstellungsdatei.":"Filen er ikke en WerkFab-innstillingsfil.",
"Datei konnte nicht geöffnet werden:":"Filen kunne ikke åpnes:",
