"Eigene Kurzbefehle: in der Symbolleiste das Gruppenmenü (▾) öffnen, beim Befehl auf ⋮ klicken → „Tastaturkurzbefehl ändern …“.":"Egne hurtigtaster: åpne gruppemenyen (▾) i verktøylinjen, klikk på ⋮ ved kommandoen → «Endre hurtigtast …».",
"Eigene Maße und Hinweise lassen sich im Blatt mit der Maus ziehen (Abstand der Maßlinie, Winkel der Hinweislinie, Radius des Winkelbogens). Zwei Ecken anklicken = Längenmaß. Einen Kreisrand in der Draufsicht anklicken = Durchmesser (bzw. Radius). Winkel: erst die Ecke, dann je einen Eckpunkt auf beiden Schenkeln. Fase: beide Enden der schrägen Kante – ergibt z. B. 2×45°. Im Textfeld hinter jedem Maß steht ein Zusatz wie ±0,1, H7 oder 4×.":"Egne mål og merknader kan dras på arket med musen (avstand til målelinjen, vinkel på henvisningslinjen, radius på vinkelbuen). Klikk på to hjørner = lengdemål. Klikk på en sirkelkant i toppvisningen = diameter (eller radius). Vinkel: først hjørnet, deretter ett hjørnepunkt på hvert ben. Fas: begge endene av den skrå kanten – gir f.eks. 2×45°. I tekstfeltet etter hvert mål står et tillegg som ±0,1, H7 eller 4×.",
