"Ein runder Fräser lässt in jeder Innenecke seinen Radius stehen – ein eckiges Gegenstück passt dann nicht hinein. Der Freistich fährt an jeder scharfen Innenecke kurz in die Ecke und zurück.{0}{1}":"En rund fres lar radiusen sin stå igjen i hvert innvendige hjørne – en kantet motdel passer da ikke inn. Avlastningen kjører kort inn i hjørnet og tilbake ved hvert skarpe innvendige hjørne.{0}{1}",
