"Erst die Fläche an dem Körper anklicken, der bewegt wird, dann die Zielfläche am anderen Körper. Der Körper wird gedreht und verschoben, bis der erste Klickpunkt auf dem zweiten liegt und die Flächen aufeinander liegen.":"Klikk først på flaten på kroppen som skal flyttes, deretter målflaten på den andre kroppen. Kroppen roteres og flyttes til det første klikkpunktet ligger på det andre og flatene ligger mot hverandre.",
"Erst die Kante an dem Körper anklicken, der bewegt wird, dann die Zielkante am anderen Körper. Gerade Kanten kommen deckungsgleich aufeinander (Mitte auf Mitte); bei Kreiskanten – Bohrung und Zapfen – werden die Achsen gleich gerichtet und die Mittelpunkte zusammengelegt.":"Klikk først på kanten på kroppen som skal flyttes, deretter målkanten på den andre kroppen. Rette kanter legges sammenfallende (midt mot midt); for sirkelkanter – hull og tapp – rettes aksene likt og midtpunktene føres sammen.",
