"Konturen folgen dem Rand der dunklen Flächen. Die Mittellinie läuft in der Mitte der Striche – passend für Gravuren und Strichzeichnungen. „Geraden, Bögen und Kreise“ erkennt gerade Kanten, scharfe Ecken, Rundungen und Kreise; „Linienzüge“ folgt dem Bild Punkt für Punkt. Den Maßstab danach bei Bedarf mit „Vorlage kalibrieren“ oder „Skalieren“ anpassen.":"Konturene følger kanten av de mørke områdene. Midtlinjen går i midten av strekene – egnet for graveringer og strektegninger. «Linjer, buer og sirkler» gjenkjenner rette kanter, skarpe hjørner, avrundinger og sirkler; «Polylinjer» følger bildet punkt for punkt. Juster målestokken etterpå ved behov med «Kalibrer mal» eller «Skaler».",
