"Kurven einer Skizze auf der Planfläche (quer zur Drehachse) mit einem angetriebenen Fräser entlang Z (X und C fahren gemeinsam; Fanuc: Polar-Interpolation G12.1). Offene Kurven werden hin und zurück gefräst. Tiefe ab Planfläche.":"Kurver i en skisse på planflaten (på tvers av dreieaksen) med en drevet fres langs Z (X og C beveger seg sammen; Fanuc: polar interpolasjon G12.1). Åpne kurver freses frem og tilbake. Dybde fra planflaten.",
"Kurven einer Skizze, die längs zur Drehachse liegt, werden auf den Umfang gewickelt und mit einem angetriebenen Fräser gefräst, der zur Achse zeigt (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Die Skizzenebene bestimmt den Winkel, an dem die Kontur sitzt; waagerechte Strecken in der Skizze werden Bögen um das Teil. Tiefe ab Außendurchmesser.":"Kurver i en skisse som ligger langs dreieaksen vikles rundt omkretsen og freses med en drevet fres som peker mot aksen (Z og C beveger seg sammen; Fanuc: sylinderinterpolasjon G7.1). Skisseplanet bestemmer vinkelen konturen ligger i; vannrette strekninger i skissen blir buer rundt delen. Dybde fra ytre diameter.",
