"Nur dort, wo das Referenzwerkzeug nicht hinkam: flache Bereiche parallel, steile Bereiche als Wasserlinie. Mit einem Werkzeug aus der Liste zählt dessen Form mit – zum Beispiel was ein Torusfräser in den Hohlkehlen stehen lässt.":"Bare der referanseverktøyet ikke kom til: flate områder parallelt, bratte områder som vannlinje. Med et verktøy fra listen teller formen med – for eksempel det en torusfres lar stå igjen i hulkilene.",
