"Nut längs der Drehachse (z. B. Passfedernut) mit einem angetriebenen Fräser, der zur Achse zeigt; die Hauptspindel hält das Teil als C-Achse. Nutbreite = Fräser-Ø. Start/Ende Z in Modell-Z; reicht die Nut bis zur Planfläche, fährt der Fräser von vorn ein, sonst taucht er am Start ein. Tiefe ab Außendurchmesser.":"Spor langs dreieaksen (f.eks. kilespor) med en drevet fres som peker mot aksen; hovedspindelen holder delen som C-akse. Sporbredde = fres-Ø. Start/slutt Z i modell-Z; når sporet til planflaten, kjører fresen inn forfra, ellers stikker den ned ved starten. Dybde fra ytre diameter.",
