"Wickelt die Skizzenkurven auf den Zylinder: X bleibt X, der Abstand quer zur Achse wird zum Bogen auf dem Abwicklungs-Ø (Drehung A). Die Skizze muss parallel zur A-Achse liegen, z. B. auf einer Tangentialebene. Gefräst wird in fester Tiefe unter der Teiloberfläche – für Gravuren, Schriften und Nuten rund um das Teil.":"Vikler skisse-kurvene rundt sylinderen: X forblir X, avstanden på tvers av aksen blir en bue på avviklings-Ø (rotasjon A). Skissen må ligge parallelt med A-aksen, f.eks. på et tangentialplan. Det freses i fast dybde under delens overflate – for gravering, skrift og spor rundt delen.",
